      "qualname": "lark/exceptions.py::UnexpectedInput.match_examples",
      "source": "def match_examples(self, p, e, t=False, u=True):
    """Allows you to detect what's wrong in the input text by matching
    against example errors.

    Given a parser instance and a dictionary mapping some label with
    some malformed syntax examples, it'll return the label for the
    example that bests matches the current error. The function will
    iterate the dictionary until it finds a matching error, and
    return the corresponding value.

    For an example usage, see `examples/error_reporting_lalr.py`

    Parameters:
        parse_fn: parse function (usually ``lark_instance.parse``)
        examples: dictionary of ``{'example_string': value}``.
        use_accepts: Recommended to keep this as ``use_accepts=True``.
    """
    assert self.state is not None, "Not supported for this exception"
    e = e.items() if isinstance(e, dict) else e
    c = (None, False)
    for i, (l, ex) in enumerate(e):
        assert not isinstance(ex, str), "Expecting a list"
        for j, m in enumerate(ex):
            try:
                p(m)
            except UnexpectedInput as ut:
                if ut.state != self.state:
                    continue
                if u and hasattr(self, 'accepts') and hasattr(ut, 'accepts') and ut.accepts != self.accepts:
                    logger.debug("Different accepts with same state[%d]: %s != %s at example [%s][%s]" % (self.state, self.accepts, ut.accepts, i, j))
                    continue
                try:
                    if ut.token == self.token:
                        logger.debug("Exact Match at example [%s][%s]" % (i, j))
                        return l
                    if t and (ut.token.type == self.token.type) and not c[-1]:
                        logger.debug("Token Type Fallback at example [%s][%s]" % (i, j))
                        c = l, True
                except AttributeError:
                    pass
                if c[0] is None:
                    logger.debug("Same State match at example [%s][%s]" % (i, j))
                    c = l, False
    return c[0]"
    },
