      "qualname": "lark/parsers/earley.py::Parser._parse",
      "source": "def _parse(self, l, cols, ts, start=None):
    def is_quasi_complete(it):
        if it.is_complete:
            return True
        q = it.advance()
        while not q.is_complete:
            if q.expect not in self.NULLABLE:
                return False
            if q.rule.origin == start and q.expect == start:
                return False
            q = q.advance()
        return True

    def scan(i, token, ts):
        ns = set()
        nts = set()
        cols.append(nts)
        tr.append({})
        nc = {}
        for it in ts:
            if match(it.expect, token):
                ni = it.advance()
                lab = (ni.s, ni.start, i)
                term = terminals.get(token.type) if isinstance(token, Token) else None
                tn = TokenNode(token, term, priority=0)
                ni.node = nc[lab] if lab in nc else nc.setdefault(lab, SymbolNode(*lab))
                ni.node.add_family(ni.s, it.rule, ni.start, it.node, tn)
                if ni.expect in self.TERMINALS:
                    ns.add(ni)
                else:
                    nts.add(ni)
        if not nts and not ns:
            expect = {i.expect.name for i in ts}
            raise UnexpectedToken(token, expect, considered_rules=set(ts), state=frozenset(i.s for i in ts))
        return ns

    match = self.term_matcher
    terminals = self.lexer_conf.terminals_by_name
    tr = [{}]
    ex = {i.expect for i in ts}
    i = 0
    for token in l.lex(ex):
        self.predict_and_complete(i, ts, cols, tr)
        ts = scan(i, token, ts)
        i += 1
        ex.clear()
        ex |= {i.expect for i in ts}
    self.predict_and_complete(i, ts, cols, tr)
    assert i == len(cols) - 1
    return ts"
    },
