      "qualname": "lark/parsers/earley_forest.py::ForestVisitor.visit",
      "source": "def visit(self, root):
    v = set()
    vd = set()
    p = []
    s = deque([root])
    vpno = getattr(self, 'visit_packed_node_out')
    vpni = getattr(self, 'visit_packed_node_in')
    vsno = getattr(self, 'visit_symbol_node_out')
    vsni = getattr(self, 'visit_symbol_node_in')
    vino = getattr(self, 'visit_intermediate_node_out', vsno)
    vini = getattr(self, 'visit_intermediate_node_in', vsni)
    vtn = getattr(self, 'visit_token_node')
    oc = getattr(self, 'on_cycle')
    while s:
        c = s[-1]
        try:
            n = next(c)
        except StopIteration:
            s.pop()
            continue
        except TypeError:
            pass
        else:
            if n is None:
                continue
            if id(n) in v:
                oc(n, p)
                continue
            s.append(n)
            continue
        if isinstance(c, TokenNode):
            vtn(c.token)
            s.pop()
            continue
        cid = id(c)
        if cid in v:
            if isinstance(c, PackedNode):
                vpno(c)
            elif c.is_intermediate:
                vino(c)
            else:
                vsno(c)
            s.pop()
            p.pop()
            v.remove(cid)
            vd.add(cid)
        elif self.single_visit and cid in vd:
            s.pop()
        else:
            v.add(cid)
            p.append(c)
            if isinstance(c, PackedNode):
                n = vpni(c)
            elif c.is_intermediate:
                n = vini(c)
            else:
                n = vsni(c)
            if n is None:
                continue
            if not isinstance(n, ForestNode):
                n = iter(n)
            elif id(n) in v:
                oc(n, p)
                continue
            s.append(n)"
